def estimate_vector_bytes(count, dimensions, bytes_per_component=4):
    if count < 0 or dimensions <= 0 or bytes_per_component <= 0:
        raise ValueError("Invalid storage parameters")
    return count * dimensions * bytes_per_component

size = estimate_vector_bytes(1_000_000, 1536)
print(f"Raw storage: {size / 1_000_000_000:.2f} GB")
